import java.util.*;

class Solution {
    int[][] memo;
    int[] pref;
    private int dp(int i, int j) {
        if (i == j) return 0;
        if (memo[i][j] != -1) return memo[i][j];
        int ans = 0;
        for (int k = i; k < j; k++) {
            int left = pref[k + 1] - pref[i];
            int right = pref[j + 1] - pref[k + 1];
            if (left < right) {
                ans = Math.max(ans, left + dp(i, k));
            } else if (right < left) {
                ans = Math.max(ans, right + dp(k + 1, j));
            } else {
                ans = Math.max(ans, left + Math.max(dp(i, k), dp(k + 1, j)));
            }
        }
        return memo[i][j] = ans;
    }
    public int stoneGameV(int[] stoneValue) {
        int n = stoneValue.length;
        memo = new int[n][n];
        for (int[] row : memo) Arrays.fill(row, -1);
        pref = new int[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + stoneValue[i];
        return dp(0, n - 1);
    }
}

var stoneGameV = function(stoneValue) {
    const n = stoneValue.length;
    const memo = Array.from({ length: n }, () => new Int32Array(n).fill(-1));
    const pref = new Int32Array(n + 1);
    for (let i = 0; i < n; i++) pref[i + 1] = pref[i] + stoneValue[i];
    function dp(i, j) {
        if (i === j) return 0;
        if (memo[i][j] !== -1) return memo[i][j];
        let ans = 0;
        for (let k = i; k < j; k++) {
            const left = pref[k + 1] - pref[i];
            const right = pref[j + 1] - pref[k + 1];
            if (left < right) {
                ans = Math.max(ans, left + dp(i, k));
            } else if (right < left) {
                ans = Math.max(ans, right + dp(k + 1, j));
            } else {
                ans = Math.max(ans, left + Math.max(dp(i, k), dp(k + 1, j)));
            }
        }
        return memo[i][j] = ans;
    }
    return dp(0, n - 1);
};
